				if callback then
					callback(selected)
				end
				return true
			end
		end
		return false
	end
	rebuild = function()
		for _, child in ipairs(list:GetChildren()) do
			if child:IsA("TextButton") then
				child:Destroy()
			end
		end
		local filterText = string.lower(searchBox and searchBox.Text or "")
		visibleCount = 0
		for index, option in ipairs(options) do
