				if option == selected then
					kept = option
					break
				end
			end
			selected = kept
			valueLabel.Text = selected ~= nil and tostring(selected) or "Select..."
			rebuild()
		end,
		SetCallback = function(cb)
			callback = H.Callback(cb)
		end,
		SetExpanded = setExpanded,
		GetExpanded = function()
			return expanded
		end,
