			end)
			if not built then tabScope:Destroy(); error(tabResult, 2) end
			return tabResult
		end)
		method(window, "CreateNotification", function(settings)
			alive()
			return UI:CreateNotification(settings)
		end)

		--// Window interactions -------------------------------------------------------
		local dragStart, startPos
		H.BindDrag(scope, topbar, function(input, began)
			if began then
				dragStart = input.Position
				startPos = main.Position
				return
			end
			local delta = input.Position - dragStart
			main.Position = UDim2.new(
				startPos.X.Scale, startPos.X.Offset + delta.X,
				startPos.Y.Scale, startPos.Y.Offset + delta.Y
			)
		end)

		local floatingLogo = make("ImageButton", {
			Name = "FloatingLogo",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, -40, 1, -40),
			Size = UDim2.fromOffset(52, 52),
			BackgroundTransparency = 1,
			Image = theme.Assets.Dragon,
			ScaleType = Enum.ScaleType.Fit,
			AutoButtonColor = false,
			ZIndex = 10,
			Visible = false,
			Parent = bounds,
		})
		make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = floatingLogo })
		make("UIStroke", { Color = C.Primary, Thickness = 1, Transparency = 0.25, Parent = floatingLogo })

		local function logoAnchorPixels()
			local position = floatingLogo.Position
			local size = bounds.AbsoluteSize
			return Vector2.new(position.X.Scale * size.X + position.X.Offset,
				position.Y.Scale * size.Y + position.Y.Offset)
		end

		local function clampAxis(value, extent, length, anchor)
			-- A screen smaller than the logo cannot contain it; center it safely instead.
			if extent <= length then return extent * anchor end
			return math.clamp(value, length * anchor, extent - length * (1 - anchor))
		end

		local function positionLogo(position)
			local size = bounds.AbsoluteSize
			if size.X <= 0 or size.Y <= 0 then return end
			local logoSize = floatingLogo.AbsoluteSize
			local anchor = floatingLogo.AnchorPoint
			floatingLogo.Position = UDim2.fromOffset(
				clampAxis(position.X, size.X, logoSize.X, anchor.X),
				clampAxis(position.Y, size.Y, logoSize.Y, anchor.Y)
			)
		end

		local logoDragStart, logoStartPos
		local logoMoved = false
		local function trackLogoMovement(input)
			if logoDragStart and (input.Position - logoDragStart).Magnitude > W.DragThreshold then
				logoMoved = true
			end
		end

		H.BindDrag(scope, floatingLogo, function(input, began)
			if began then
				logoMoved = false
				logoDragStart = input.Position
				-- Resolve both scale and offset before switching to pixel-only coordinates.
				logoStartPos = logoAnchorPixels()
				positionLogo(logoStartPos)
				return
			end
			trackLogoMovement(input)
			local delta = input.Position - logoDragStart
			positionLogo(logoStartPos + Vector2.new(delta.X, delta.Y))
		end, trackLogoMovement)

		method(window, "Hide", function()
			alive()
			main.Visible = false
			floatingLogo.Visible = false
		end)
		method(window, "Minimize", function()
			alive()
			main.Visible = false
			positionLogo(logoAnchorPixels())
			floatingLogo.Visible = true
		end)
		local function restore()
			alive()
			floatingLogo.Visible = false
			main.Visible = true
			main.Size = WINDOW_SIZE
		end
		method(window, "Show", restore)
		method(window, "Restore", restore)
		method(window, "IsVisible", function()
			return not scope.Destroyed and gui.Enabled and main.Visible
		end)
		method(window, "Destroy", function() scope:Destroy() end)

		scope:Connect(minimizeBtn.Activated, function() window.Minimize() end)

		scope:Connect(floatingLogo.Activated, function(input)
			if input and (input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch) then
				-- Activated and the gesture's end listener may run in either order.
				trackLogoMovement(input)
				if logoMoved then return end
			end
			window.Restore()
		end)

		scope:Connect(closeBtn.Activated, function() window.Hide() end)

		scope:Connect(UserInputService.InputBegan, function(input, gameProcessed)
			if gameProcessed or UserInputService:GetFocusedTextBox() then return end
			if input.KeyCode == Enum.KeyCode.RightShift then
				window.Restore()
			end
		end)

		-- Use the inset-aware bounds for scaling too, with no minimum that can overflow
		-- tiny screens. Keep at most one viewport listener when CurrentCamera changes.
		local function updateLayout()
			local size = bounds.AbsoluteSize
			if size.X <= 0 or size.Y <= 0 then return end
			uiScale.Scale = math.min(size.X / W.ViewportWidth, size.Y / W.ViewportHeight, W.MaxScale)
			if floatingLogo.Visible then positionLogo(logoAnchorPixels()) end
		end

		local viewportConnection
		local function bindCamera()
			if viewportConnection then
				viewportConnection:Disconnect()
				viewportConnection = nil
			end
			local camera = workspace.CurrentCamera
			if camera then
				viewportConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
					if not scope.Destroyed then updateLayout() end
				end)
			end
			updateLayout()
		end
		scope:Add(function()
			if viewportConnection then
				viewportConnection:Disconnect()
				viewportConnection = nil
			end
		end)
		scope:Connect(workspace:GetPropertyChangedSignal("CurrentCamera"), bindCamera)
		scope:Connect(bounds:GetPropertyChangedSignal("AbsoluteSize"), updateLayout)
		bindCamera()
		gui.Parent = playerGui
		updateLayout()

		assert(not scope.Destroyed, "Window destroyed during publication")
		return window
	end)
	if not ok then
		if scope then scope:Destroy() else gui:Destroy() end
		error(result, 2)
	end
	return result
end

end

__factories["Helpers.lua"] = function(__require)
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local Helpers = {}

function Helpers.new(theme)
	local H = {}
	local scopes = setmetatable({}, { __mode = "k" })

	function H.GetScope(root)
		return scopes[root]
	end

	function H.Number(value, default, name)
		if value == nil then value = default end
		assert(type(value) == "number" and value == value and math.abs(value) < math.huge,
			(name or "Value") .. " must be a finite number")
		return value
	end

	function H.Callback(callback)
		assert(callback == nil or type(callback) == "function", "Callback must be a function or nil")
		return callback
	end

	function H.Options(values)
		if values == nil then return {} end
		assert(type(values) == "table", "Options/values must be an array")
		local count = 0
		for key in pairs(values) do
			assert(type(key) == "number" and key >= 1 and key % 1 == 0, "Options/values must be a dense array")
			count += 1
		end
		local result, seen = {}, {}
		for index = 1, count do
			local value = values[index]
			assert(type(value) == "string" or (type(value) == "number" and value == value and math.abs(value) < math.huge),
				"Options/values must be a dense array of strings or finite numbers")
			if not seen[value] then
				seen[value] = true
				table.insert(result, value)
			end
		end
		return result
	end

	function H.Make(className, props)
		local inst = Instance.new(className)
		-- Invalid properties must not leave a partially constructed Instance behind.
		local ok, message = pcall(function()
			for key, value in pairs(props) do
				if key ~= "Parent" then inst[key] = value end
			end
			inst.Parent = props.Parent
		end)
		if not ok then inst:Destroy(); error(message, 2) end
		return inst
	end

	function H.Tween(inst, duration, goal)
		local animation = TweenService:Create(inst, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), goal)
		local destroying, completed
		local function disconnect()
			if destroying then destroying:Disconnect(); destroying = nil end
			if completed then completed:Disconnect(); completed = nil end
		end
		destroying = inst.Destroying:Connect(function()
			disconnect()
			animation:Cancel()
		end)
		completed = animation.Completed:Connect(disconnect)
		animation:Play()
		return animation
	end

	function H.CardRow(parent, name, height)
		local row = H.Make("Frame", {
			Name = name, Size = UDim2.new(1, 0, 0, height), BackgroundColor3 = theme.Colors.Card,
			BorderSizePixel = 0, Parent = parent,
		})
		H.Make("UICorner", { CornerRadius = UDim.new(0, theme.Dimensions.CornerRadius), Parent = row })
		H.Make("UIStroke", { Color = theme.Colors.Border, Thickness = 1, Parent = row })
		return row
	end

	function H.Scope(root)
		local scope = { Destroyed = false }
		scopes[root] = scope
		local cleanups = {}
		local destroying
		local function clean()
			if scope.Destroyed then return end
			scope.Destroyed = true
			scopes[root] = nil
			if destroying then destroying:Disconnect(); destroying = nil end
			for index = #cleanups, 1, -1 do
				local ok, message = pcall(cleanups[index])
				if not ok then warn("Astral cleanup: " .. tostring(message)) end
			end
			table.clear(cleanups)
		end
		function scope:Add(cleanup)
			assert(type(cleanup) == "function", "Cleanup must be a function")
			if self.Destroyed then cleanup() else table.insert(cleanups, cleanup) end
			return cleanup
		end
		function scope:Connect(signal, callback)
			assert(not self.Destroyed, "Scope is destroyed")
			local connection = signal:Connect(function(...)
				if not self.Destroyed then callback(...) end
			end)
			self:Add(function() connection:Disconnect() end)
			return connection
		end
		function scope:Destroy()
			if self.Destroyed then return end
			clean()
			-- Explicit parent teardown is synchronous even with deferred Roblox
			-- signals: child gestures/capture must stop before Destroy returns.
			for _, descendant in ipairs(root:GetDescendants()) do
				local childScope = scopes[descendant]
				if childScope then childScope:Destroy() end
			end
			root:Destroy()
		end
		destroying = root.Destroying:Connect(clean)
		return scope
	end

	-- Global input listeners exist only during an active gesture. Track the exact
	-- touch object so another finger cannot move or terminate this gesture.
	function H.BindDrag(scope, target, onUpdate, onEnd)
		local active, changed, ended, focusLost
		local function stop(notify)
			local previous = active
			active = nil
			if changed then changed:Disconnect(); changed = nil end
			if ended then ended:Disconnect(); ended = nil end
			if focusLost then focusLost:Disconnect(); focusLost = nil end
			if previous and notify and onEnd and not scope.Destroyed then onEnd(previous) end
		end
		scope:Add(function() stop(false) end)
		scope:Connect(target.InputBegan, function(input)
			local kind = input.UserInputType
			if active or (kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch) then return end
			active = input
			changed = UserInputService.InputChanged:Connect(function(update)
				if scope.Destroyed or not active then return end
				if (kind == Enum.UserInputType.Touch and update == active)
					or (kind == Enum.UserInputType.MouseButton1 and update.UserInputType == Enum.UserInputType.MouseMovement) then
					onUpdate(update, false)
				end
			end)
			ended = UserInputService.InputEnded:Connect(function(update)
				if update == active or (kind == Enum.UserInputType.MouseButton1 and update.UserInputType == kind) then stop(true) end
			end)
			focusLost = UserInputService.WindowFocusReleased:Connect(function() stop(false) end)
			onUpdate(input, true)
		end)
	end

	return H
end

return Helpers

end

__factories["Theme.lua"] = function(__require)
-- Defaults are copied per library instance; requiring this module creates no UI.
local Theme = {}

local function copy(value)
	if type(value) ~= "table" then return value end
	local result = {}
	for key, child in pairs(value) do result[key] = copy(child) end
	return result
end

local defaults = {
	Colors = {
		Background = Color3.fromHex("10111A"), Sidebar = Color3.fromHex("151622"),
		Card = Color3.fromHex("1B1C2A"), Primary = Color3.fromHex("A879FF"),
		Secondary = Color3.fromHex("8055D9"), Border = Color3.fromHex("303044"),
		Text = Color3.fromHex("F4F2FA"), SubText = Color3.fromHex("9693A9"),
	},
	Fonts = { Regular = Enum.Font.Gotham, Medium = Enum.Font.GothamMedium, Bold = Enum.Font.GothamBold },
	NotificationColors = {
		Info = Color3.fromHex("8055D9"), Success = Color3.fromHex("6BCB77"),
		Warning = Color3.fromHex("F4B860"), Error = Color3.fromHex("FF6B6B"),
	},
	Dimensions = { RowHeight = 44, CornerRadius = 6, WindowWidth = 650, WindowHeight = 420,
		TopbarHeight = 65, SidebarWidth = 150, NotificationWidth = 260 },
	Assets = { Dragon = "rbxassetid://101879171935546" },
	Window = { ViewportWidth = 740, ViewportHeight = 500, MaxScale = 1, DragThreshold = 6 },
}

function Theme.new(overrides)
	local result = copy(defaults)
	if overrides == nil then return result end
	assert(type(overrides) == "table", "Theme must be a table")
	for group, values in pairs(overrides) do
		assert(type(result[group]) == "table" and type(values) == "table", "Unknown theme group: " .. tostring(group))
		for key, value in pairs(values) do
			local expected = result[group][key]
			assert(expected ~= nil and typeof(value) == typeof(expected), "Invalid theme field: " .. group .. "." .. tostring(key))
			if type(value) == "number" then
				assert(value == value and value > 0 and value < math.huge, "Theme dimensions/constants must be finite and positive")
			elseif typeof(expected) == "EnumItem" then
				assert(value.EnumType == expected.EnumType, "Theme font must be Enum.Font")
			end
			result[group][key] = value
		end
	end
	return result
end

return Theme

end

__factories["init.lua"] = function(__require)
